    n = len(s)
    results = []

    # Function to determine if a substring s[l:r+1] is lexicographically minimal
    def is_lexicographically_minimal(l, r):
        # If there's a smaller lexicographical substring on the left
        if l > 0 and s[l - 1] < s[l]:
            return True
        # If there's a smaller lexicographical substring on the right
        if r < n - 1 and s[r + 1] < s[r]:
            return True
        return False

    for k in range(n):
        l, r = k, k
        can_move = True

        while can_move:
            can_move = False
            # Ann's turn
            for l_prime in range(l, -1, -1):
                for r_prime in range(r, n):
                    if is_lexicographically_minimal(l_prime, r_prime):
                        l, r = l_prime, r_prime
                        can_move = True
                        break
                if can_move:
                    break
            if can_move:
