                        if is_lexicographically_minimal(l_prime, r_prime):
                            l, r = l_prime, r_prime
                            can_move = True
                            break
                    if can_move:
                        break

        # If Ann can't move, Mike wins; otherwise, Ann wins
        if can_move:
            results.append("Ann")
