    dp = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):
        for l in range(n - length + 1):
            r = l + length - 1
            if s[l] < s[r]:
                dp[l][r] = 1
            elif s[l] > s[r]:
                dp[l][r] = -1
            else:
                dp[l][r] = dp[l + 1][r - 1]

    results = []
    for k in range(n):
